public class InnerCallAnalyticsCategoryRuleFactory(Action<Humidifier.Transcribe.CallAnalyticsCategoryTypes.Rule> factoryAction = null) : SubResourceFactory<Humidifier.Transcribe.CallAnalyticsCategoryTypes.Rule>
{

    internal InnerCallAnalyticsCategoryNonTalkTimeFilterFactory NonTalkTimeFilterFactory { get; set; }

    internal InnerCallAnalyticsCategorySentimentFilterFactory SentimentFilterFactory { get; set; }

    internal InnerCallAnalyticsCategoryTranscriptFilterFactory TranscriptFilterFactory { get; set; }

    internal InnerCallAnalyticsCategoryInterruptionFilterFactory InterruptionFilterFactory { get; set; }

    protected override Humidifier.Transcribe.CallAnalyticsCategoryTypes.Rule Create()
    {
        var ruleResult = CreateRule();
        factoryAction?.Invoke(ruleResult);

        return ruleResult;
    }

    private Humidifier.Transcribe.CallAnalyticsCategoryTypes.Rule CreateRule()
    {
        var ruleResult = new Humidifier.Transcribe.CallAnalyticsCategoryTypes.Rule();

        return ruleResult;
    }
    public override void CreateChildren(Humidifier.Transcribe.CallAnalyticsCategoryTypes.Rule result)
    {
        base.CreateChildren(result);

        result.NonTalkTimeFilter ??= NonTalkTimeFilterFactory?.Build();
        result.SentimentFilter ??= SentimentFilterFactory?.Build();
        result.TranscriptFilter ??= TranscriptFilterFactory?.Build();
        result.InterruptionFilter ??= InterruptionFilterFactory?.Build();
    }

} // End Of Class

